  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} [${IS_PRODUCTION ? 'production' : 'development'}]`);
});

module.exports = app;
```

